#!/usr/bin/env python3
"""Implement the incident analyzer here. See /workspace/public for examples."""
import json
import sys
for line in sys.stdin:
    try:
        value = json.loads(line)
        result = {"id": value.get("id") if isinstance(value, dict) else None,
                  "status": "error", "error": "not_implemented"}
    except (ValueError, TypeError):
        result = {"id": None, "status": "error", "error": "malformed_json"}
    print(json.dumps(result))
